/* Public website. Words and settings: js/content.js. Look: css/theme.css. Normally you do not edit this file. */
(function () {
  const S = SITE, $ = (s) => document.querySelector(s);
  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const U = (u) => (String(u).startsWith("/uploads/") ? API_BASE + u : u);
  const safe = (u) => (/^https?:\/\//i.test(String(u || "")) ? u : "");
  let lang = localStorage.getItem("lang") || S.defaultLang;
  const T = (k) => (S.t[lang] && S.t[lang][k]) || S.t.en[k] || k;
  const L = (o) => (typeof o === "string" ? o : (o && (o[lang] || o.en)) || "");
  const lab = (pre, v) => (S.t.en[pre + v] ? T(pre + v) : v || "");
  let posts = [], sig = "";
  const F = { port: "all", market: "all", rent: "all" };
  let alarm = JSON.parse(localStorage.getItem("alarm") || "null");
  const all = (kind) => (S.seeds[kind] || []).concat(posts.filter((p) => p.kind === kind));
  const find = (id) => Object.values(S.seeds).flat().concat(posts).find((p) => String(p.id) === String(id));
  const RENT = ["bld", "guest", "apt", "shopr", "offr", "wh"];

  const ICONS = {
    instagram: '<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/>',
    facebook: '<path d="M15 3h-2.5A4.5 4.5 0 0 0 8 7.5V10H5v4h3v7h4v-7h3l1-4h-4V7.5c0-.3.2-.5.5-.5H15z"/>',
    youtube: '<rect x="2.5" y="5.5" width="19" height="13" rx="4"/><path d="M10 9.5l5 2.5-5 2.5z"/>',
    tiktok: '<path d="M15 3v11.5a4 4 0 1 1-4-4"/><path d="M15 3c.4 2.6 2 4.2 5 4.5"/>',
    telegram: '<path d="M21 4L3 11l6 2.2L11 20l3-4 5 3.5z"/><path d="M9 13.2L21 4"/>',
    whatsapp: '<path d="M3 21l1.6-4.7A9 9 0 1 1 8 19.6z"/><path d="M9 8.5c0 3.5 3 6.5 6.5 6.5l1.2-1.3-2.2-1-.9.8c-1-.4-2-1.4-2.4-2.4l.8-.9-1-2.2z"/>',
    linkedin: '<rect x="3" y="9" width="4" height="12"/><circle cx="5" cy="5" r="2"/><path d="M10 9h4v2c.7-1.3 2-2.2 3.7-2.2 3 0 3.3 2 3.3 4.7V21h-4v-6c0-1.3 0-2.5-1.5-2.5S14 13.7 14 15v6h-4z"/>',
  };
  const social = () => '<div class="social-row">' + S.social.map((s) => `<a class="soc" style="--c:${esc(s.color)}" href="${esc(safe(s.url) || "#")}" target="_blank" rel="noopener" aria-label="${esc(s.label)}"><svg viewBox="0 0 24 24">${ICONS[s.key] || ""}</svg><span>${esc(s.label)}</span></a>`).join("") + "</div>";

  /* ---------- cards ---------- */
  const cover = (p) => {
    const m = p.media || [], i = m.find((x) => x.type === "image"), v = m.find((x) => x.type === "video");
    if (i) return `<img src="${esc(U(i.url))}" alt="${esc(p.title)}">`;
    if (v) return `<video src="${esc(U(v.url))}#t=0.5" muted preload="metadata"></video><span class="play">&#9654;</span>`;
    return '<img src="images/placeholder.jpg" alt="">';
  };
  const badge = (p) => (p.kind === "portfolio" ? lab("f_", p.type) : p.kind === "hub" ? T("nav_hub") : lab("t_", p.type));
  const card = (p) => `<article class="card"><div class="ph">${cover(p)}<span class="badge">${esc(badge(p))}</span></div><div class="cb"><h3>${esc(p.title)}</h3><small>${[p.location, p.area ? p.area + " m²" : "", p.year, p.stage].filter(Boolean).map(esc).join(" · ")}</small>${p.price ? `<b class="price">${esc(p.price)}</b>` : ""}${p.purpose ? `<small>${esc(T("p_purpose"))}: ${esc(lab("p_", p.purpose))}</small>` : ""}<button class="link" data-view="${esc(p.id)}">${T("view")}</button></div></article>`;
  const tabs = (key, list) => '<div class="tabs">' + list.map(([v, l]) => `<button class="tab${F[key] === v ? " on" : ""}" data-f="${key}|${esc(v)}">${esc(l)}</button>`).join("") + "</div>";
  const grid = (items) => (items.length ? `<div class="grid g3">${items.map(card).join("")}</div>` : `<p class="empty">${T("none")}</p>`);
  const filt = (items, key) => items.filter((p) => F[key] === "all" || p.type === F[key]);

  /* ---------- page ---------- */
  function render() {
    const y = window.scrollY, lg = S.langs.find((l) => l.code === lang) || S.langs[0];
    document.documentElement.lang = lg.code; document.documentElement.dir = lg.dir || "ltr"; document.title = S.pageTitle;
    const nav = [["home", "#home"], ["services", "#services"], ["portfolio", "#portfolio"], ["hub", "#hub"], ["market", "#market"], ["rent", "#rent"]];
    const links = nav.map(([k, h]) => `<a href="${h}">${T("nav_" + k)}</a>`).join("");
    const hub = all("hub");
    $("#app").innerHTML =
      `<header><div class="wrap bar"><a href="#home" class="logo">${S.logo ? `<img src="${esc(S.logo)}" alt="logo">` : ""}${S.showNameNextToLogo || !S.logo ? `<span>${esc(S.name)}</span>` : ""}</a><nav class="main">${links}<a href="#contact" class="btn gold sm">${T("nav_contact")}</a></nav>` +
      `<div class="tools"><select id="lang" aria-label="Language">${S.langs.map((l) => `<option value="${l.code}"${l.code === lang ? " selected" : ""}>${l.label}</option>`).join("")}</select><button class="iconbtn" data-act="alarm" aria-label="${T("al_btn")}">&#128276; <span class="lbl">${T("al_btn")}</span>${alarm ? '<i class="dot"></i>' : ""}</button>` +
      `<button class="iconbtn" data-act="more" aria-label="${T("menu_more")}" title="${T("menu_more")}">&#8942;</button><div class="dd" id="dd"><button data-act="bids">${T("nav_bids")}</button><button data-act="laws">${T("nav_laws")}</button><button data-act="map">${T("nav_map")}</button><button data-act="owner">${T("owner_login")}</button></div><button class="iconbtn" id="menuBtn" aria-label="Menu">&#9776;</button></div></div><nav id="mobile">${links}<a href="#contact">${T("nav_contact")}</a></nav></header>` +
      `<main><section class="hero" id="home"><img src="${esc(S.heroImage)}" alt=""><div class="wrap"><small>${T("hero_tag")}</small><h1>${T("hero_title")}</h1><p>${T("hero_text")}</p><div class="cta"><a href="#portfolio" class="btn gold">${T("hero_b1")}</a><a href="#contact" class="btn ghost">${T("hero_b2")}</a></div></div></section>` +
      `<div class="quick"><div class="wrap"><div><button data-post="market"><b>+</b>${T("market_btn")}</button><button data-post="rent"><b>+</b>${T("rent_btn")}</button><button data-go="#contact"><b>&#9742;</b>${T("hero_b2")}</button></div></div></div>` +
      `<section class="sec" id="services"><div class="wrap"><h2 class="t">${T("svc_title")}</h2><p class="sub">${T("svc_text")}</p><div class="grid g2">${[1, 2, 3, 4].map((i) => `<article class="svc"><h3>${T("s" + i + "t")}</h3><p>${T("s" + i + "d")}</p></article>`).join("")}</div></div></section>` +
      `<section class="sec alt" id="portfolio"><div class="wrap"><h2 class="t">${T("port_title")}</h2><p class="sub">${T("port_text")}</p>${tabs("port", [["all", T("f_all")], ["civil", T("f_civil")], ["office", T("f_office")], ["design", T("f_design")]])}${grid(filt(all("portfolio"), "port"))}</div></section>` +
      `<section class="sec dark" id="hub"><div class="wrap"><div class="two"><div><h2 class="t">${T("hub_title")}</h2><p class="sub">${T("hub_text")}</p><div class="acts"><a href="#contact" class="btn gold">${T("nav_contact")}</a></div></div><ul>${T("hub_pts").split("|").map((x) => `<li><b>${esc(x)}</b></li>`).join("")}</ul></div>` +
      `<div class="row hubrow"><h3>${T("hub_posts")}</h3><button class="btn gold" data-post="hub">${T("hub_btn")}</button></div>${hub.length ? `<div class="grid g3">${hub.map(card).join("")}</div>` : `<p class="empty">${T("none")}</p>`}</div></section>` +
      `<section class="sec" id="market"><div class="wrap"><div class="row"><div><h2 class="t">${T("market_title")}</h2><p class="sub">${T("market_text")}</p></div><div class="acts"><button class="btn" data-post="market">${T("market_btn")}</button><button class="btn out" data-act="mine">${T("my_posts")}</button></div></div>${tabs("market", [["all", T("f_all")], ["land", T("t_land")], ["house", T("t_house")], ["unfin", T("t_unfin")]])}${grid(filt(all("market"), "market"))}</div></section>` +
      `<section class="sec alt" id="rent"><div class="wrap"><div class="row"><div><h2 class="t">${T("rent_title")}</h2><p class="sub">${T("rent_text")}</p></div><button class="btn" data-post="rent">${T("rent_btn")}</button></div>${tabs("rent", [["all", T("f_all")]].concat(RENT.map((x) => [x, T("t_" + x)])))}${grid(filt(all("rent"), "rent"))}</div></section>` +
      `<section class="sec" id="contact"><div class="wrap contact"><div><h2 class="t">${T("contact_title")}</h2><p class="sub">${T("contact_text")}</p></div><form class="formbox form" id="contactForm"><label>${T("f_name")}<input required name="name"></label><label>${T("f_phone")}<input required type="tel" name="phone"></label><label class="full">${T("f_email")}<input type="email" name="email"></label><label class="full">${T("f_service")}<select name="service"><option>${T("s1t")}</option><option>${T("s2t")}</option><option>${T("s3t")}</option><option>${T("s4t")}</option><option>${T("other_svc")}</option></select></label><label class="full">${T("f_msg")}<textarea required name="message" id="cmsg" rows="4"></textarea></label><div class="full"><button class="btn gold" type="submit">${T("f_send")}</button><p class="ok" id="cok" role="status" hidden></p></div></form></div></section></main>` +
      `<footer><div class="wrap"><div class="cols"><div><b>${esc(S.name)}</b>${esc(S.address)}<br>${esc(S.phone)}<br>${esc(S.email)}</div><div><b>${T("nav_home")}</b>${nav.slice(1).map(([k, h]) => `<a href="${h}">${T("nav_" + k)}</a><br>`).join("")}</div><div><b>${T("ft_contact")}</b><a href="#contact">${T("nav_contact")}</a><br><a href="admin.html">${T("owner_login")}</a></div></div>${social()}<p class="copy">&copy; ${new Date().getFullYear()} ${esc(S.name)}. ${T("rights")}</p></div></footer>`;
    window.scrollTo(0, y);
  }

  /* ---------- modal ---------- */
  const open = (html, wide) => { $("#mod").className = "modal" + (wide ? " wide" : ""); $("#mod").innerHTML = html; $("#ov").classList.add("open"); };
  const closeM = () => $("#ov").classList.remove("open");
  const closeBtn = () => `<div class="acts"><button class="btn out" data-close>${T("close")}</button></div>`;
  const mediaHTML = (m) => m.type === "image" ? `<img class="mi" src="${esc(U(m.url))}" alt="">` : m.type === "video" ? `<video class="mi" src="${esc(U(m.url))}" controls preload="metadata"></video>` : `<a class="btn out sm" href="${esc(U(m.url))}" target="_blank">${T("open_pdf")}: ${esc(m.name || "")}</a> `;
  function detail(id) {
    const p = find(id); if (!p) return;
    const rows = [[T("p_loc"), p.location], [T("p_area"), p.area], [T("p_purpose"), p.purpose ? lab("p_", p.purpose) : ""], [T("p_price"), p.price], [T("deadline"), p.deadline]].filter((r) => r[1]);
    open(`<div class="mgal">${(p.media || []).filter((m) => m.type !== "pdf").map(mediaHTML).join("") || '<img class="mi" src="images/placeholder.jpg" alt="">'}</div><div class="mb"><h3>${esc(p.title)}</h3><p class="meta">${esc(badge(p))}${p.year ? " · " + esc(p.year) : ""}${p.stage ? " · " + esc(p.stage) : ""}</p>${rows.map((r) => `<p><b>${esc(r[0])}:</b> ${esc(r[1])}</p>`).join("")}<p class="pre">${esc(p.details)}</p><div class="acts"><button class="btn gold" data-ask="${esc(p.id)}">${T("inquire")}</button><button class="btn out" data-close>${T("close")}</button></div></div>`);
  }
  const readFiles = (inp, store, prev) => { store.length = 0; prev.innerHTML = ""; [...inp.files].slice(0, 6).forEach((f) => { if (f.size > 25e6) { alert(f.name + ": max 25 MB"); return; } const r = new FileReader(); r.onload = () => { store.push({ name: f.name, dataUrl: r.result }); prev.insertAdjacentHTML("beforeend", f.type.startsWith("image") ? `<img src="${r.result}" alt="">` : `<span>${esc(f.name)}</span>`); }; r.readAsDataURL(f); }); };
  const sendJSON = async (url, b) => { const r = await fetch(API_BASE + url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b) }); const j = await r.json(); if (!r.ok) throw 0; return j; };

  function postForm(kind) {
    const types = { market: ["land", "house", "unfin"], rent: RENT, hub: [] }[kind], files = [], tt = { market: "market_btn", rent: "rent_btn", hub: "hub_btn" }[kind];
    open(`<form class="mb form" id="pf" style="grid-template-columns:1fr"><h3>${T(tt)}</h3>${types.length ? `<label>${T("p_type")}<select name="type">${types.map((x) => `<option value="${x}">${lab("t_", x)}</option>`).join("")}</select></label>` : ""}<label>${T("p_title")}<input required name="title" maxlength="150"></label><label>${T("p_loc")}<input required name="location"></label>${kind !== "hub" ? `<label>${T("p_area")}<input name="area" inputmode="numeric"></label><label>${T("p_price")}<input name="price"></label>` : ""}${kind === "rent" ? `<label>${T("p_purpose")}<select name="purpose">${["shop", "live", "office", "other"].map((x) => `<option value="${x}">${T("p_" + x)}</option>`).join("")}</select></label>` : ""}<label>${T("p_details")}<textarea required name="details" rows="3"></textarea></label><label>${T("p_media")}<input type="file" id="pfile" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><div class="prev" id="pprev"></div><label>${T("p_yourname")}<input required name="name"></label><label>${T("p_yourphone")}<input required type="tel" name="phone"></label><label>${T("f_email")}<input type="email" name="email"></label><div class="acts"><button class="btn gold" type="submit">${T("p_submit")}</button><button type="button" class="btn out" data-close>${T("p_cancel")}</button></div><p class="ok" id="pmsg" role="status" hidden></p></form>`);
    $("#pfile").onchange = (e) => readFiles(e.target, files, $("#pprev"));
    $("#pf").onsubmit = async (e) => {
      e.preventDefault(); const b = Object.fromEntries(new FormData(e.target)); b.kind = kind; b.media = files; const m = $("#pmsg"); m.hidden = false; m.textContent = "...";
      try {
        const j = await sendJSON("/api/submit", b); const codes = JSON.parse(localStorage.getItem("codes") || "[]"); codes.unshift({ code: j.code, title: b.title }); localStorage.setItem("codes", JSON.stringify(codes.slice(0, 30)));
        m.innerHTML = `${T("p_sent")} <b>${esc(j.code)}</b><br>${T("p_review")}`; e.target.querySelector(".acts").remove();
      } catch (x) { m.textContent = T("server_off"); }
    };
  }
  async function mine() {
    const codes = JSON.parse(localStorage.getItem("codes") || "[]"); let h = `<div class="mb"><h3>${T("my_posts")}</h3>`;
    if (!codes.length) h += `<p>${T("none")}</p>`;
    for (const c of codes) {
      let s = "?"; try { const r = await fetch(API_BASE + "/api/status/" + c.code); const j = await r.json(); s = T("st_" + j.status) + (j.note ? ` (${T("reason")}: ${esc(j.note)})` : ""); } catch (e) { s = T("server_off"); }
      h += `<div class="listrow"><b>${esc(c.title)}</b> <small>#${esc(c.code)}</small><br>${s}</div>`;
    }
    open(h + closeBtn() + "</div>");
  }

  /* ---------- bids, laws, map (open only when clicked) ---------- */
  function bidsModal() {
    const bids = all("bid");
    open(`<div class="mb"><h3>${T("bids_title")}</h3><p class="meta">${T("bids_text")}</p>${bids.length ? bids.map((x) => `<div class="listrow"><h4>${esc(x.title)}</h4><small>${[x.deadline && T("deadline") + ": " + x.deadline, x.price].filter(Boolean).map(esc).join(" · ")}</small><p class="pre">${esc(x.details)}</p>${x.criteria ? `<p><b>${T("criteria")}:</b></p><p class="pre">${esc(x.criteria)}</p>` : ""}${(x.media || []).length ? `<p><b>${T("docs")}:</b></p><div class="acts">${x.media.map((m) => `<a class="btn out sm" href="${esc(U(m.url))}" target="_blank">${esc(m.name || T("open_pdf"))}</a>`).join("")}</div>` : ""}<div class="acts"><button class="btn gold sm" data-apply="${esc(x.id)}">${T("ap_btn")}</button></div></div>`).join("") : `<p class="empty">${T("no_bids")}</p>`}${closeBtn()}</div>`, true);
  }
  function applyForm(id) {
    const b = find(id), files = []; if (!b) return;
    open(`<form class="mb form" id="af2" style="grid-template-columns:1fr"><h3>${T("ap_btn")}</h3><p class="meta">${esc(b.title)}</p><label>${T("p_yourname")}<input required name="name"></label><label>${T("p_yourphone")}<input required type="tel" name="phone"></label><label>${T("f_email")}<input type="email" name="email"></label><label>${T("f_msg")}<textarea name="message" rows="3"></textarea></label><label>${T("ap_docs")}<input type="file" id="afile" multiple accept="application/pdf,image/jpeg,image/png"></label><div class="prev" id="aprev"></div><div class="acts"><button class="btn gold" type="submit">${T("p_submit")}</button><button type="button" class="btn out" data-close>${T("p_cancel")}</button></div><p class="ok" id="amsg" role="status" hidden></p></form>`);
    $("#afile").onchange = (e) => readFiles(e.target, files, $("#aprev"));
    $("#af2").onsubmit = async (e) => {
      e.preventDefault(); const d = Object.fromEntries(new FormData(e.target)); d.bidId = id; d.media = files; const m = $("#amsg"); m.hidden = false; m.textContent = "...";
      try { await sendJSON("/api/apply", d); m.textContent = T("ap_sent"); e.target.querySelector(".acts").remove(); } catch (x) { m.textContent = T("server_off"); }
    };
  }
  function lawsModal() {
    const rows = S.laws.map((x) => ({ t: L(x.title), pdf: x.pdf, url: safe(x.url), media: [] })).concat(all("law").map((x) => ({ t: x.title, pdf: "", url: safe(x.link), media: x.media || [], type: x.type })));
    open(`<div class="mb"><h3>${T("laws_title")}</h3><p class="meta">${T("laws_text")}</p>${rows.map((x) => `<div class="listrow"><h4>${esc(x.t)}</h4>${x.type ? `<small>${esc(x.type)}</small>` : ""}<div class="acts">${x.pdf ? `<a class="btn sm" href="${esc(x.pdf)}" target="_blank">${T("open_pdf")}</a>` : ""}${x.media.map((m) => `<a class="btn sm" href="${esc(U(m.url))}" target="_blank">${T("open_pdf")}: ${esc(m.name || "")}</a>`).join("")}${x.url ? `<a class="btn out sm" href="${esc(x.url)}" target="_blank" rel="noopener">${T("open_site")}</a>` : ""}${!x.pdf && !x.url && !x.media.length ? `<small>${T("not_added")}</small>` : ""}</div></div>`).join("")}${closeBtn()}</div>`, true);
  }
  const mapEmbed = (u) => {
    if (/google\.[^/]+\/maps\/embed/i.test(u)) return u;
    const m = u.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/) || u.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/) || u.match(/[?&](?:q|ll|query)=(-?\d+\.\d+)(?:,|%2C)(-?\d+\.\d+)/);
    if (!m) return ""; const la = +m[1], lo = +m[2], d = 0.008;
    return `https://www.openstreetmap.org/export/embed.html?bbox=${lo - d},${la - d * 0.7},${lo + d},${la + d * 0.7}&layer=mapnik&marker=${la},${lo}`;
  };
  function mapModal(i) {
    const list = S.maps.map((m) => ({ n: L(m.name), l: safe(m.link) })).concat(all("map").map((m) => ({ n: m.title, l: safe(m.link) }))).filter((m) => m.l);
    i = Math.min(i || 0, Math.max(list.length - 1, 0)); const cur = list[i], emb = cur ? mapEmbed(cur.l) : "";
    open(`<div class="mb"><h3>${T("map_title")}</h3>${list.length ? `<div class="tabs">${list.map((m, k) => `<button class="tab${k === i ? " on" : ""}" data-mapi="${k}">${esc(m.n)}</button>`).join("")}</div>${emb ? `<iframe class="map" title="map" loading="lazy" src="${esc(emb)}"></iframe>` : ""}<div class="acts"><a class="btn gold" target="_blank" rel="noopener" href="${esc(cur.l)}">${T("open_map")}</a></div>` : `<p class="empty">${T("map_empty")}</p>`}${closeBtn()}</div>`, true);
  }

  /* ---------- alarm ---------- */
  let ctx, ringT;
  const beep = () => { if (!ctx) return; const o = ctx.createOscillator(), g = ctx.createGain(); o.frequency.value = 880; o.connect(g); g.connect(ctx.destination); g.gain.setValueAtTime(0.3, ctx.currentTime); o.start(); o.stop(ctx.currentTime + 0.25); };
  const stopRing = () => { clearInterval(ringT); $("#ringBox").hidden = true; };
  function ring(p) {
    $("#ringBox").hidden = false; $("#ringBox").innerHTML = `<b>&#128276; ${T("al_new")}</b><br>${esc(p.title)}<div class="acts"><button class="btn gold sm" data-ring="${esc(p.id)}">${T("view")}</button><button class="btn ghost sm" data-act="stop">${T("al_stop")}</button></div>`;
    clearInterval(ringT); let n = 0; beep(); ringT = setInterval(() => { beep(); if (++n > 40) stopRing(); }, 1000);
    if (window.Notification && Notification.permission === "granted") new Notification(T("al_new"), { body: p.title });
    if (navigator.vibrate) navigator.vibrate([300, 150, 300]);
  }
  const matches = (p) => { if (!alarm) return false; if (alarm.cat !== "any" && p.kind !== alarm.cat) return false; const k = (alarm.kw || "").toLowerCase().trim(); return !k || [p.title, p.location, p.details, p.type].join(" ").toLowerCase().includes(k); };
  async function load(first) {
    const before = sig; try { const r = await fetch(API_BASE + "/api/posts"); posts = await r.json(); } catch (e) { return; }
    sig = JSON.stringify(posts.map((p) => p.id + ":" + p.approvedAt));
    if (alarm && !first) { const fresh = posts.filter((p) => (p.approvedAt || p.createdAt) > alarm.last && matches(p)); if (fresh.length) ring(fresh[0]); }
    if (alarm) { alarm.last = Math.max(alarm.last, ...posts.map((p) => p.approvedAt || p.createdAt), 0); localStorage.setItem("alarm", JSON.stringify(alarm)); }
    const typing = document.activeElement && /INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName);
    if (sig !== before && !$("#ov").classList.contains("open") && !typing) render();
  }
  function alarmForm() {
    const cats = [["any", T("al_any")], ["market", T("nav_market")], ["rent", T("nav_rent")], ["hub", T("nav_hub")], ["bid", T("nav_bids")]];
    open(`<form class="mb form" id="af" style="grid-template-columns:1fr"><h3>&#128276; ${T("al_title")}</h3><p>${T("al_text")}</p><label>${T("al_cat")}<select name="cat">${cats.map(([v, l]) => `<option value="${v}"${alarm && alarm.cat === v ? " selected" : ""}>${esc(l)}</option>`).join("")}</select></label><label>${T("al_kw")}<input name="kw" value="${esc(alarm ? alarm.kw : "")}"></label>${alarm ? `<p class="ok">${T("al_active")}</p>` : ""}<div class="acts"><button class="btn gold" type="submit">${T("al_on")}</button>${alarm ? `<button type="button" class="btn out" data-act="alarmoff">${T("al_off")}</button>` : ""}<button type="button" class="btn out" data-close>${T("close")}</button></div></form>`);
    $("#af").onsubmit = (e) => {
      e.preventDefault(); const f = Object.fromEntries(new FormData(e.target));
      try { ctx = ctx || new (window.AudioContext || window.webkitAudioContext)(); ctx.resume(); } catch (x) {}
      if (window.Notification && Notification.permission === "default") Notification.requestPermission();
      alarm = { cat: f.cat, kw: f.kw, last: Date.now() }; localStorage.setItem("alarm", JSON.stringify(alarm)); beep(); closeM(); render();
    };
  }

  /* ---------- events ---------- */
  document.addEventListener("click", (e) => {
    const dd = $("#dd"); if (dd && !e.target.closest("[data-act=more]") && !e.target.closest("#dd")) dd.classList.remove("open");
    const t = e.target.closest("[data-f],[data-view],[data-post],[data-act],[data-close],[data-ask],[data-ring],[data-go],[data-apply],[data-mapi],#menuBtn,#mobile a"); if (!t) { if (e.target.id === "ov") closeM(); return; }
    const a = t.dataset.act;
    if (t.dataset.f) { const [k, v] = t.dataset.f.split("|"); F[k] = v; render(); }
    else if (t.dataset.view) detail(t.dataset.view);
    else if (t.dataset.post) postForm(t.dataset.post);
    else if (t.dataset.close !== undefined) closeM();
    else if (t.dataset.go) location.hash = t.dataset.go;
    else if (t.dataset.apply) applyForm(t.dataset.apply);
    else if (t.dataset.mapi) mapModal(+t.dataset.mapi);
    else if (t.dataset.ask) { const p = find(t.dataset.ask); closeM(); render(); const m = $("#cmsg"); if (m && p) m.value = `Re: ${p.title} (#${p.id})`; location.hash = "#contact"; }
    else if (t.dataset.ring) { stopRing(); detail(t.dataset.ring); }
    else if (a === "more") $("#dd").classList.toggle("open");
    else if (a === "bids") { $("#dd").classList.remove("open"); bidsModal(); }
    else if (a === "laws") { $("#dd").classList.remove("open"); lawsModal(); }
    else if (a === "map") { $("#dd").classList.remove("open"); mapModal(0); }
    else if (a === "owner") location.href = "admin.html";
    else if (a === "alarm") alarmForm();
    else if (a === "alarmoff") { alarm = null; localStorage.removeItem("alarm"); closeM(); render(); }
    else if (a === "mine") mine();
    else if (a === "stop") stopRing();
    else if (t.id === "menuBtn") $("#mobile").classList.toggle("open");
    else if (t.closest("#mobile")) $("#mobile").classList.remove("open");
  });
  document.addEventListener("change", (e) => { if (e.target.id === "lang") { lang = e.target.value; localStorage.setItem("lang", lang); render(); } });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeM(); });
  document.addEventListener("submit", async (e) => {
    if (e.target.id !== "contactForm") return; e.preventDefault(); const b = Object.fromEntries(new FormData(e.target)), ok = $("#cok");
    try { await sendJSON("/api/contact", b); e.target.reset(); ok.textContent = T("f_thanks"); } catch (x) { ok.textContent = T("server_off"); }
    ok.hidden = false;
  });
  render(); load(true); setInterval(() => load(false), 30000);
})();
